scenario-engine {"thingId": "kz.kentash:scenario-engine", "policyId": "default:basic_policy", "attributes": {"name": "Сценарии «что если»: активные и журнал", "kind": "module", "_isType": false, "_parents": "kz.kentash:mine", "catalog": "[{\"id\": \"equipment_failure\", \"title\": \"Отказ оборудования с ремонтом\", \"about\": \"Физическая недоступность актива → ограничение цепочки → наряд, бригада, материалы и восстановление. Отмена сценария не ремонтирует актив.\", \"params\": {\"asset\": {\"type\": \"choice\", \"options\": [\"sag-motor\", \"tail-pump\", \"conc-conveyor-1\", \"fuel-unload-pump\"], \"default\": \"sag-motor\"}}}, {\"id\": \"road\", \"title\": \"Закрыть участок дороги\", \"about\": \"Участок исключается из маршрутов. При закрытии всех доступных съездов карьер отрезан, самосвалы ниже встают, ККД питается со склада; закрытие заезда к забою перераспределяет самосвалы по другим забоям.\", \"params\": {\"seg\": {\"type\": \"choice\", \"options\": [\"ramp-upper\", \"ramp-mid\", \"ramp-lower\", \"haul-plant\", \"haul-dump\", \"service\", \"access-F1\", \"access-F2\", \"access-F3\"], \"default\": \"ramp-upper\"}}}, {\"id\": \"shovel_down\", \"title\": \"Отказ экскаватора\", \"about\": \"Экскаватор останавливается; его очередь самосвалов уходит на другие забои.\", \"params\": {\"id\": {\"type\": \"choice\", \"options\": [\"EX-1\", \"EX-2\", \"EX-3\"], \"default\": \"EX-1\"}}}, {\"id\": \"truck_down\", \"title\": \"Самосвал выведен из работы\", \"about\": \"Самосвал уходит в ремонтный бокс; парк и производительность снижаются.\", \"params\": {\"id\": {\"type\": \"choice\", \"options\": [\"TR-01\", \"TR-02\", \"TR-03\", \"TR-04\", \"TR-05\", \"TR-06\"], \"default\": \"TR-03\"}}}, {\"id\": \"crusher_stop\", \"title\": \"Остановка ККД\", \"about\": \"Руда идёт на перегрузочный склад; фабрика работает со склада КДР, пока он не иссякнет.\", \"params\": {}}, {\"id\": \"grid_out\", \"title\": \"Обесточивание ГПП-110 кВ\", \"about\": \"Стоят электрические экскаваторы, 